package com.personal.routemanager;
import static org.junit.Assert.*;
import android.content.*;
import android.webkit.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import org.robolectric.android.controller.ActivityController;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class MainActivityTest {
 @Before public void clear(){RuntimeEnvironment.getApplication().getSharedPreferences("route_manager",0).edit().clear().commit();}
 @Test public void shellHasSeparateIdentityAndNoNetworkOrWidgets()throws Exception{ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).setup();try{MainActivity activity=controller.get();assertEquals("com.personal.routemanager",activity.getPackageName());WebSettings settings=activity.webForTests().getSettings();assertTrue(settings.getJavaScriptEnabled());assertTrue(settings.getBlockNetworkLoads());assertFalse(settings.getAllowFileAccess());assertFalse(settings.getAllowContentAccess());assertFalse(settings.supportMultipleWindows());android.content.pm.PackageInfo info=activity.getPackageManager().getPackageInfo(activity.getPackageName(),android.content.pm.PackageManager.GET_RECEIVERS|android.content.pm.PackageManager.GET_SERVICES|android.content.pm.PackageManager.GET_PERMISSIONS);assertTrue(info.receivers==null||info.receivers.length==0);assertTrue(info.services==null||info.services.length==0);if(info.requestedPermissions!=null)for(String permission:info.requestedPermissions)assertFalse(permission.equals("android.permission.INTERNET")||permission.equals("android.permission.POST_NOTIFICATIONS"));assertEquals("{}",activity.bridgeForTests().readState());assertFalse(activity.bridgeForTests().writeState("invalid"));}finally{controller.pause().stop().destroy();}}
 private WebResourceRequest request(String value,boolean gesture){return new WebResourceRequest(){public android.net.Uri getUrl(){return android.net.Uri.parse(value);}public boolean isForMainFrame(){return true;}public boolean isRedirect(){return false;}public boolean hasGesture(){return gesture;}public String getMethod(){return "GET";}public java.util.Map<String,String> getRequestHeaders(){return java.util.Collections.emptyMap();}};}
 @Test public void linksUseTheBrowserAndBlockAutomaticOrUnsafeNavigation(){ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).setup();try{MainActivity a=controller.get();WebView web=a.webForTests();WebViewClient client=web.getWebViewClient();client.shouldOverrideUrlLoading(web,request("javascript:alert(1)",true));client.shouldOverrideUrlLoading(web,request("https://example.org/automatic",false));assertNull(Shadows.shadowOf(a).getNextStartedActivity());client.shouldOverrideUrlLoading(web,request("https://example.org/notes",true));Intent intent=Shadows.shadowOf(a).getNextStartedActivity();assertNotNull(intent);assertEquals(Intent.ACTION_VIEW,intent.getAction());assertEquals("https://example.org/notes",intent.getDataString());assertTrue(intent.hasCategory(Intent.CATEGORY_BROWSABLE));}finally{controller.pause().stop().destroy();}}
 @Test public void foregroundReturnRequestsTodaysRouteAfterReadiness(){ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).setup();try{MainActivity a=controller.get();a.bridgeForTests().ready();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();controller.pause().resume();assertTrue(Shadows.shadowOf(a.webForTests()).getLastEvaluatedJavascript().contains("RouteManager.openToday"));assertEquals(1f,a.webForTests().getAlpha(),0f);}finally{controller.pause().stop().destroy();}}
 @Test public void exportCopiesExactPlainTextAndSharesThroughAChooser(){ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).setup();try{MainActivity a=controller.get();String text="G200 · Monday\n1. Customer — Account 00123 — Weekly";assertTrue(a.bridgeForTests().copyText(text));android.content.ClipboardManager clipboard=(android.content.ClipboardManager)a.getSystemService(android.content.Context.CLIPBOARD_SERVICE);assertEquals(text,clipboard.getPrimaryClip().getItemAt(0).getText().toString());assertTrue(a.bridgeForTests().shareText(text));Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();Intent chooser=Shadows.shadowOf(a).getNextStartedActivity();assertEquals(Intent.ACTION_CHOOSER,chooser.getAction());Intent send=chooser.getParcelableExtra(Intent.EXTRA_INTENT);assertEquals(Intent.ACTION_SEND,send.getAction());assertEquals("text/plain",send.getType());assertEquals(text,send.getStringExtra(Intent.EXTRA_TEXT));assertFalse(a.bridgeForTests().copyText(""));assertFalse(a.bridgeForTests().shareText(null));assertFalse(a.bridgeForTests().shareText("x".repeat(200001)));}finally{controller.pause().stop().destroy();}}
}
